from robot.api import logger
import re
import random

LOG_HEAD = LOG_END = '*' * 8

__all__ = [
    "parse_output_with_ps_format_to_dict",
    "get_pod_and_container_name",
    "is_in_different_node"

]


def parse_output_with_ps_format_to_dict(output):
    pods_info = {}
    keys = []
    if 'No resources found' in output:
        raise Exception('No pods found in the current environment')
    for line in output.splitlines():
        if not keys:
            if line.strip().startswith('NAME'):
                line = re.sub(r'(\S+) (\S+)', r"\g<1>_\g<2>", line).strip()
                keys.extend([key.lower().replace(" ", "_") for key in line.split()])
                continue
        items = line.split()
        if len(items) != len(keys):
            restarts_index = keys.index('restarts')
            if items[restarts_index] != 0:
                for i in len(keys), len(items):
                    items.pop(restarts_index + 1)
            if len(items) != len(keys):
                raise Exception('No pods found in the current environment')
        pod_info = {}
        for i, key in enumerate(keys):
            pod_info[key] = items[i]
        if pod_info:
            pods_info[pod_info['name']] = pod_info
    return pods_info


def get_pod_and_container_name(pod_container_mapping, pod_abbr, ctr_abbr=None, pod_index=None):
    pods = [pod for pod in pod_container_mapping.keys() if pod_abbr in pod]
    pods.sort()
    if len(pods) == 1:
        pod_full_name = pods[0]
    elif len(pods) > 1:
        if pod_index:
            pod_full_name = pods[pod_index]
        else:
            pod_full_name = random.choice(pods)
    else:
        raise Exception('Not find pod {} in current vdu'.format(pod_abbr))

    if ctr_abbr is not None:
        ctr_name_list = [container for container in pod_container_mapping[pod_full_name] if ctr_abbr in container]
        if len(ctr_name_list) == 1:
            ctr_full_name = ctr_name_list[0]
        elif len(ctr_name_list) > 1:
            ctr_full_name = random.choice(ctr_name_list)
        else:
            raise Exception('Not find container {} in pod {}'.format(ctr_abbr, pod_full_name))
        return pod_full_name, ctr_full_name
    else:
        return pod_full_name, None


def is_in_different_node(pod_info, pod_abbr):
    node_list = []
    pod_abbr = '-' + pod_abbr + '-'
    for pod in pod_info:
        if pod_abbr in pod:
            node_list.append(pod_info[pod]['node'])
    final_node_list = list(set(node_list))
    if len(final_node_list) > 1:
        return True
    elif len(final_node_list) == 1:
        return False
    else:
        logger.debug('{} {} pod are not found in {}'.format(LOG_HEAD, pod_abbr, LOG_END))
